import WebSocket from 'ws';
import http from 'http';
import ldap from 'ldapjs';

interface ProxyHeaders {
  'x-forwarded-for'?: string;
  'x-real-ip'?: string;
  'x-auth-user'?: string;
  'x-request-id'?: string;
}

interface SearchRequest {
  action: 'search';
  department: string;
  attributes?: string[];
}

interface LookupRequest {
  action: 'lookup';
  userId: string;
}

type ClientMessage = SearchRequest | LookupRequest;

class LDAPConnectionPool {
  private client: ldap.Client;
  private baseDN = 'dc=corp,dc=example,dc=com';

  constructor() {
    const bindPw = process.env.LDAP_BIND_PW;
    if (!bindPw) {
      // Refuse to start with an empty/missing bind password to avoid an
      // unauthenticated (anonymous) bind against the directory.
      throw new Error('LDAP_BIND_PW environment variable must be set');
    }

    this.client = ldap.createClient({ url: 'ldap://ldap.internal:389' });

    // Handle client-level errors so an unhandled 'error' event cannot crash
    // the process on connection failures.
    this.client.on('error', (err) => {
      console.error('LDAP client error:', err && err.message ? err.message : err);
    });

    this.client.bind('cn=svc-reader,ou=services,' + this.baseDN, bindPw, (err) => {
      if (err) {
        console.error('LDAP bind failed:', err.message);
      }
    });
  }

  async search(filter: string, base: string, attributes: string[]): Promise<any[]> {
    return new Promise((resolve, reject) => {
      const opts: ldap.SearchOptions = {
        filter,
        scope: 'sub',
        attributes,
        sizeLimit: 100,
        timeLimit: 10
      };
      const results: any[] = [];
      this.client.search(base, opts, (err, res) => {
        if (err) return reject(err);
        res.on('searchEntry', (entry) => results.push(entry.pojo));
        res.on('error', reject);
        res.on('end', () => resolve(results));
      });
    });
  }
}

class InputSanitizer {
  private static readonly LDAP_SPECIAL = /[\\*()\x00]/g;
  private static readonly ALLOWED_DEPT_CHARS = /^[a-zA-Z0-9\s\-\.]+$/;
  private static readonly ALLOWED_ATTRS = ['cn', 'mail', 'telephoneNumber', 'title', 'department', 'manager'];

  static sanitizeLdapValue(input: string): string {
    return input.replace(InputSanitizer.LDAP_SPECIAL, (char) => {
      return '\\' + char.charCodeAt(0).toString(16).padStart(2, '0');
    });
  }

  static validateDepartment(dept: string): boolean {
    return dept.length > 0 && dept.length <= 64 && InputSanitizer.ALLOWED_DEPT_CHARS.test(dept);
  }

  static validateUserId(uid: string): boolean {
    return /^[a-zA-Z][a-zA-Z0-9._-]{2,31}$/.test(uid);
  }

  static filterAttributes(requested?: string[]): string[] {
    if (!requested || requested.length === 0) return ['cn', 'mail', 'department'];
    return requested.filter(a => InputSanitizer.ALLOWED_ATTRS.includes(a));
  }

  static validateCallerDN(dn: string): boolean {
    // Strict DN format: only allow expected proxy-provided DNs
    return /^cn=[a-zA-Z0-9._\-]+,ou=[a-zA-Z]+,dc=corp,dc=example,dc=com$/.test(dn);
  }
}

class DirectoryService {
  private pool: LDAPConnectionPool;
  private baseDN = 'dc=corp,dc=example,dc=com';

  constructor(pool: LDAPConnectionPool) {
    this.pool = pool;
  }

  async searchByDepartment(department: string, attributes: string[]): Promise<any[]> {
    const sanitized = InputSanitizer.sanitizeLdapValue(department);
    const filter = `(&(objectClass=person)(department=${sanitized}))`;
    return this.pool.search(filter, `ou=people,${this.baseDN}`, attributes);
  }

  async lookupUser(userId: string, callerIdentity: string): Promise<any[]> {
    const sanitizedUid = InputSanitizer.sanitizeLdapValue(userId);
    const sanitizedCaller = InputSanitizer.sanitizeLdapValue(callerIdentity);
    const filter = `(&(objectClass=person)(uid=${sanitizedUid})(|(manager=${sanitizedCaller})(uid=${sanitizedCaller})))`;
    return this.pool.search(filter, `ou=people,${this.baseDN}`, ['cn', 'mail', 'title', 'department']);
  }
}

function extractCallerIdentity(headers: ProxyHeaders): string | null {
  const authUser = headers['x-auth-user'];
  if (!authUser) return null;
  // Validate the DN format from the proxy
  if (!InputSanitizer.validateCallerDN(authUser)) return null;
  return authUser;
}

function createServer(): http.Server {
  const server = http.createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end('WebSocket Directory Service v2.1.0');
  });

  const pool = new LDAPConnectionPool();
  const directoryService = new DirectoryService(pool);

  const wss = new WebSocket.Server({
    server,
    verifyClient: (info) => {
      // Only accept connections from our reverse proxy subnet
      const forwarded = info.req.headers['x-forwarded-for'] as string;
      return !!forwarded; // Proxy always sets this header
    }
  });

  wss.on('connection', (ws, req) => {
    const headers = req.headers as unknown as ProxyHeaders;
    const callerIdentity = extractCallerIdentity(headers);

    if (!callerIdentity) {
      ws.send(JSON.stringify({ error: 'Authentication required' }));
      ws.close();
      return;
    }

    ws.on('message', async (data) => {
      try {
        const msg: ClientMessage = JSON.parse(data.toString());

        if (msg.action === 'search') {
          if (!InputSanitizer.validateDepartment(msg.department)) {
            ws.send(JSON.stringify({ error: 'Invalid department name' }));
            return;
          }
          const attrs = InputSanitizer.filterAttributes(msg.attributes);
          const results = await directoryService.searchByDepartment(msg.department, attrs);
          ws.send(JSON.stringify({ results }));

        } else if (msg.action === 'lookup') {
          if (!InputSanitizer.validateUserId(msg.userId)) {
            ws.send(JSON.stringify({ error: 'Invalid user ID format' }));
            return;
          }
          const results = await directoryService.lookupUser(msg.userId, callerIdentity);
          ws.send(JSON.stringify({ results }));
        }
      } catch (e) {
        ws.send(JSON.stringify({ error: 'Request processing failed' }));
      }
    });
  });

  return server;
}

const server = createServer();
server.listen(8080, '127.0.0.1', () => {
  console.log('Directory WebSocket service listening on 127.0.0.1:8080');
});
